   pure module subroutine cfc_atomic_radius2_eval(d_a, R_a, a1, fade_start, fade_width, max_deriv, &
                                           rr0_aa, rr1_r_aa, rr2_rr_aa)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Atomic-term exponent prefactor a1 (Diedenhofen-Klamt 2018: -15)
      real(wp), intent(in) :: a1
      !> Fade onset in sigma = ||d||/R - 1, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma, finite and > 0 (read only when a center is past fade_start)
      real(wp), intent(in) :: fade_width
      !> Highest spatial-derivative order to accumulate (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d2/(dR_a dR_a) of the order-0 spatial derivative, where R_a and R_a are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr0_aa
      !> d2/(dR_a dR_a) of the order-1 spatial derivative, where R_a and R_a are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr1_r_aa(3)
      !> d2/(dR_a dR_a) of the order-2 spatial derivative, where R_a and R_a are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr2_rr_aa(3, 3)

      !> Reduced distance sigma = ||d||/R - 1 of each center
      real(wp) :: sg_a
      !> Fade: band end, reciprocal width, raw and clamped s, t, ds/dsigma
      real(wp) :: band_end, inv_delta, sr, fs, ft, dsdd
      !> d^j P_n/ds^j of the reduced smoothstep polynomial, w = s**(n+1) P_n(s)
      real(wp) :: fp0, fp1, fp2, fp3, fp4
      !> Powers s**k of the fade variable
      real(wp) :: fsp1, fsp2, fsp3, fsp4, fsp5
      !> Unfaded factor exp(a1 sigma_a)
      real(wp) :: fu
      !> Faded radial factor and its sigma derivatives d^j/dsigma^j, e_a = w_a exp(a1 sigma_a)
      real(wp) :: e_a(0:4)
      !> Common subexpressions of the radial jets
      real(wp) :: fj0, fj1, fj2, fj3, fj4, fj5, fj6, fj7, fj8

      sg_a = (sqrt(d_a(1)*d_a(1) + d_a(2)*d_a(2) + d_a(3)*d_a(3)) - R_a)*(1.0_wp/R_a)
      if (sg_a > fade_start) then
         ! In or beyond a center's band: faded term, the strip kernel's fade
         if (.not. fade_width > 0.0_wp) error stop &
            "cfc_atomic_radius2_eval: fade_width must be positive"
         band_end = fade_start + fade_width
         ! Beyond the band of a center: w = 0, nothing to add
         if (sg_a >= band_end) return
         inv_delta = 1.0_wp/fade_width
         select case (max_deriv)
         case (0)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a1*sg_a)
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               e_a(0) = fj0*fu
               e_a(1) = fu*(a1*fj0 + fj1)
               e_a(2) = &
                  fu*((a1*a1)*fj0 + 2.0_wp*a1*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs &
                  + fp2*fsp2))
               x0 = (d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))
               rr0_aa = rr0_aa + ((2.0_wp*e_a(1)*sqrt(x0) + e_a(2)*x0/R_a)/(R_a*R_a*R_a))
            end block
         case (1)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fp3 = -1680.0_wp*ft - 210.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a1*sg_a)
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               fj2 = (a1*a1)
               fj3 = fp2*fsp2
               fj4 = fp1*fs
               fj5 = (dsdd*dsdd)*fsp3*(fj3 + 10.0_wp*fj4 + 20.0_wp*fp0)
               e_a(0) = fj0*fu
               e_a(1) = fu*(a1*fj0 + fj1)
               e_a(2) = fu*(2.0_wp*a1*fj1 + fj0*fj2 + fj5)
               e_a(3) = &
                  fu*((a1*a1*a1)*fj0 + 3.0_wp*a1*fj5 + (dsdd*dsdd*dsdd)*fsp2*(15.0_wp*fj3 + &
                  60.0_wp*fj4 + 60.0_wp*fp0 + fp3*fsp3) + 3.0_wp*fj1*fj2)
               x0 = 1.0_wp/(R_a*R_a*R_a)
               x1 = (d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))
               x2 = sqrt(x1)
               x3 = 2.0_wp*e_a(1)
               x4 = 1.0_wp/R_a
               x5 = e_a(2)*x4
               x6 = 1.0_wp/x2
               x7 = x0*(x3*x6 + x4*x6*(2.0_wp*e_a(2)*x2 + e_a(3)*x1*x4) + 2.0_wp*x5)
               rr0_aa = rr0_aa + (x0*(x1*x5 + x2*x3))
               rr1_r_aa(1) = rr1_r_aa(1) + (d_a(1)*x7)
               rr1_r_aa(2) = rr1_r_aa(2) + (d_a(2)*x7)
               rr1_r_aa(3) = rr1_r_aa(3) + (d_a(3)*x7)
            end block
         case default
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
               real(wp) :: x17, x18, x19, x20, t_rr2_rr_aa_01, t_rr2_rr_aa_02, t_rr2_rr_aa_12

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fp3 = -1680.0_wp*ft - 210.0_wp
               fp4 = 1680.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a1*sg_a)
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               fj2 = (a1*a1)
               fj3 = fp2*fsp2
               fj4 = fp1*fs
               fj5 = (dsdd*dsdd)*fsp3*(fj3 + 10.0_wp*fj4 + 20.0_wp*fp0)
               fj6 = (a1*a1*a1)
               fj7 = fp3*fsp3
               fj8 = (dsdd*dsdd*dsdd)*fsp2*(15.0_wp*fj3 + 60.0_wp*fj4 + fj7 + 60.0_wp*fp0)
               e_a(0) = fj0*fu
               e_a(1) = fu*(a1*fj0 + fj1)
               e_a(2) = fu*(2.0_wp*a1*fj1 + fj0*fj2 + fj5)
               e_a(3) = fu*(3.0_wp*a1*fj5 + fj0*fj6 + 3.0_wp*fj1*fj2 + fj8)
               e_a(4) = &
                  fu*((a1*a1*a1*a1)*fj0 + 4.0_wp*a1*fj8 + (dsdd*dsdd*dsdd*dsdd)*fs*(120.0_wp*fj3 + &
                  240.0_wp*fj4 + 20.0_wp*fj7 + 120.0_wp*fp0 + fp4*fsp4) + 4.0_wp*fj1*fj6 + &
                  6.0_wp*fj2*fj5)
               x0 = 1.0_wp/(R_a*R_a*R_a)
               x1 = (d_a(1)*d_a(1))
               x2 = (d_a(2)*d_a(2))
               x3 = (d_a(3)*d_a(3))
               x4 = x1 + x2 + x3
               x5 = sqrt(x4)
               x6 = 2.0_wp*e_a(1)
               x7 = 1.0_wp/R_a
               x8 = e_a(2)*x7
               x9 = 2.0_wp*x8
               x10 = 1.0_wp/x5
               x11 = x10*x6
               x12 = x0*(x10*x7*(2.0_wp*e_a(2)*x5 + e_a(3)*x4*x7) + x11 + x9)
               x13 = e_a(4)*x0
               x14 = x6/(x4*sqrt(x4))
               x15 = x9/x4
               x16 = e_a(3)/(R_a*R_a)
               x17 = 5.0_wp*x10*x16
               x18 = x11 + x16*x5 + 4.0_wp*x8
               x19 = x13 - x14 + x15 + x17
               x20 = d_a(1)*x0*x19
               rr0_aa = rr0_aa + (x0*(x4*x8 + x5*x6))
               rr1_r_aa(1) = rr1_r_aa(1) + (d_a(1)*x12)
               rr1_r_aa(2) = rr1_r_aa(2) + (d_a(2)*x12)
               rr1_r_aa(3) = rr1_r_aa(3) + (d_a(3)*x12)
               rr2_rr_aa(1, 1) = rr2_rr_aa(1, 1) + (x0*(x1*x13 - x1*x14 + x1*x15 + x1*x17 + x18))
               t_rr2_rr_aa_01 = d_a(2)*x20
               rr2_rr_aa(1, 2) = rr2_rr_aa(1, 2) + t_rr2_rr_aa_01
               rr2_rr_aa(2, 1) = rr2_rr_aa(2, 1) + t_rr2_rr_aa_01
               t_rr2_rr_aa_02 = d_a(3)*x20
               rr2_rr_aa(1, 3) = rr2_rr_aa(1, 3) + t_rr2_rr_aa_02
               rr2_rr_aa(3, 1) = rr2_rr_aa(3, 1) + t_rr2_rr_aa_02
               rr2_rr_aa(2, 2) = rr2_rr_aa(2, 2) + (x0*(x13*x2 - x14*x2 + x15*x2 + x17*x2 + x18))
               t_rr2_rr_aa_12 = d_a(2)*d_a(3)*x0*x19
               rr2_rr_aa(2, 3) = rr2_rr_aa(2, 3) + t_rr2_rr_aa_12
               rr2_rr_aa(3, 2) = rr2_rr_aa(3, 2) + t_rr2_rr_aa_12
               rr2_rr_aa(3, 3) = rr2_rr_aa(3, 3) + (x0*(x13*x3 - x14*x3 + x15*x3 + x17*x3 + x18))
            end block
         end select
         return
      end if

      ! Plateau: plain term, w = 1
      select case (max_deriv)
      case (0)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2

            x0 = 1.0_wp/R_a
            x1 = (d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))
            x2 = sqrt(x1)
            rr0_aa = rr0_aa + (a1*(a1*x0*x1 + 2.0_wp*x2)*exp(-a1*(-x0*x2 + 1.0_wp))/(R_a*R_a*R_a))
         end block
      case (1)
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7

            x0 = (d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))
            x1 = sqrt(x0)
            x2 = 1.0_wp/R_a
            x3 = a1*x2
            x4 = x0*x3 + 2.0_wp*x1
            x5 = a1*exp(-a1*(-x1*x2 + 1.0_wp))/(R_a*R_a*R_a)
            x6 = 1.0_wp/x1
            x7 = x5*(x3*x4*x6 + 2.0_wp*x3 + 2.0_wp*x6)
            rr0_aa = rr0_aa + (x4*x5)
            rr1_r_aa(1) = rr1_r_aa(1) + (d_a(1)*x7)
            rr1_r_aa(2) = rr1_r_aa(2) + (d_a(2)*x7)
            rr1_r_aa(3) = rr1_r_aa(3) + (d_a(3)*x7)
         end block
      case default
         block
            !> Common subexpressions and symmetry orbits
            real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
            real(wp) :: x17, x18, x19, x20, x21, t_rr2_rr_aa_01, t_rr2_rr_aa_02, t_rr2_rr_aa_12

            x0 = (d_a(1)*d_a(1))
            x1 = (d_a(2)*d_a(2))
            x2 = (d_a(3)*d_a(3))
            x3 = x0 + x1 + x2
            x4 = sqrt(x3)
            x5 = 1.0_wp/R_a
            x6 = a1*x5
            x7 = x3*x6 + 2.0_wp*x4
            x8 = 1.0_wp/(R_a*R_a*R_a)
            x9 = a1*x8*exp(-a1*(-x4*x5 + 1.0_wp))
            x10 = 2.0_wp*x6
            x11 = 1.0_wp/x4
            x12 = 2.0_wp*x11
            x13 = x9*(x10 + x11*x6*x7 + x12)
            x14 = 2.0_wp/(x3*sqrt(x3))
            x15 = (a1*a1*a1)*x8
            x16 = x10/x3
            x17 = (a1*a1)/(R_a*R_a)
            x18 = 5.0_wp*x11*x17
            x19 = x12 + x17*x4 + 4.0_wp*x6
            x20 = -x14 + x15 + x16 + x18
            x21 = d_a(1)*x20*x9
            rr0_aa = rr0_aa + (x7*x9)
            rr1_r_aa(1) = rr1_r_aa(1) + (d_a(1)*x13)
            rr1_r_aa(2) = rr1_r_aa(2) + (d_a(2)*x13)
            rr1_r_aa(3) = rr1_r_aa(3) + (d_a(3)*x13)
            rr2_rr_aa(1, 1) = rr2_rr_aa(1, 1) + (x9*(-x0*x14 + x0*x15 + x0*x16 + x0*x18 + x19))
            t_rr2_rr_aa_01 = d_a(2)*x21
            rr2_rr_aa(1, 2) = rr2_rr_aa(1, 2) + t_rr2_rr_aa_01
            rr2_rr_aa(2, 1) = rr2_rr_aa(2, 1) + t_rr2_rr_aa_01
            t_rr2_rr_aa_02 = d_a(3)*x21
            rr2_rr_aa(1, 3) = rr2_rr_aa(1, 3) + t_rr2_rr_aa_02
            rr2_rr_aa(3, 1) = rr2_rr_aa(3, 1) + t_rr2_rr_aa_02
            rr2_rr_aa(2, 2) = rr2_rr_aa(2, 2) + (x9*(-x1*x14 + x1*x15 + x1*x16 + x1*x18 + x19))
            t_rr2_rr_aa_12 = d_a(2)*d_a(3)*x20*x9
            rr2_rr_aa(2, 3) = rr2_rr_aa(2, 3) + t_rr2_rr_aa_12
            rr2_rr_aa(3, 2) = rr2_rr_aa(3, 2) + t_rr2_rr_aa_12
            rr2_rr_aa(3, 3) = rr2_rr_aa(3, 3) + (x9*(-x14*x2 + x15*x2 + x16*x2 + x18*x2 + x19))
         end block
      end select

   end subroutine cfc_atomic_radius2_eval

   pure module subroutine cfc_pair_radius2_eval(d_a, d_b, R_a, R_b, a2, c_par, fade_start, fade_width, &
                                         max_deriv, rr0_aa, rr0_ab, rr0_bb, rr1_r_aa, rr1_r_ab, &
                                         rr1_r_bb, rr2_rr_aa, rr2_rr_ab, rr2_rr_bb)
      !> Displacement r - r_a
      real(wp), intent(in) :: d_a(3)
      !> Displacement r - r_b
      real(wp), intent(in) :: d_b(3)
      !> Radius of atom a
      real(wp), intent(in) :: R_a
      !> Radius of atom b
      real(wp), intent(in) :: R_b
      !> Pair-term exponent prefactor a2 (Diedenhofen-Klamt 2018: -9)
      real(wp), intent(in) :: a2
      !> Pair-term coupling constant c (Diedenhofen-Klamt 2018: 5)
      real(wp), intent(in) :: c_par
      !> Fade onset in sigma = ||d||/R - 1, as passed to the strip kernel; huge(0.0_wp) for no fade
      real(wp), intent(in) :: fade_start
      !> Fade band width in sigma, finite and > 0 (read only when a center is past fade_start)
      real(wp), intent(in) :: fade_width
      !> Highest spatial-derivative order to accumulate (0..2); a larger value is treated as 2
      integer, intent(in) :: max_deriv
      !> d2/(dR_a dR_a) of the order-0 spatial derivative, where R_a and R_a are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr0_aa
      !> d2/(dR_a dR_b) of the order-0 spatial derivative, where R_a and R_b are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr0_ab
      !> d2/(dR_b dR_b) of the order-0 spatial derivative, where R_b and R_b are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr0_bb
      !> d2/(dR_a dR_a) of the order-1 spatial derivative, where R_a and R_a are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr1_r_aa(3)
      !> d2/(dR_a dR_b) of the order-1 spatial derivative, where R_a and R_b are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr1_r_ab(3)
      !> d2/(dR_b dR_b) of the order-1 spatial derivative, where R_b and R_b are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr1_r_bb(3)
      !> d2/(dR_a dR_a) of the order-2 spatial derivative, where R_a and R_a are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr2_rr_aa(3, 3)
      !> d2/(dR_a dR_b) of the order-2 spatial derivative, where R_a and R_b are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr2_rr_ab(3, 3)
      !> d2/(dR_b dR_b) of the order-2 spatial derivative, where R_b and R_b are the atoms' radii;
      !> no trailing index, radii are scalars
      real(wp), intent(inout) :: rr2_rr_bb(3, 3)

      !> Reduced distance sigma = ||d||/R - 1 of each center
      real(wp) :: sg_a, sg_b
      !> Fade: band end, reciprocal width, raw and clamped s, t, ds/dsigma
      real(wp) :: band_end, inv_delta, sr, fs, ft, dsdd
      !> d^j P_n/ds^j of the reduced smoothstep polynomial, w = s**(n+1) P_n(s)
      real(wp) :: fp0, fp1, fp2, fp3, fp4
      !> Powers s**k of the fade variable
      real(wp) :: fsp1, fsp2, fsp3, fsp4, fsp5
      !> Unfaded factor exp(a2 (sigma_a + sigma_b)), on g_a
      real(wp) :: fu
      !> Faded radial factor and its sigma derivatives d^j/dsigma^j, g = w exp(a2 sigma) per center, g_b without its exp (carried by g_a)
      real(wp) :: g_a(0:4), g_b(0:4)
      !> Common subexpressions of the radial jets
      real(wp) :: fj0, fj1, fj2, fj3, fj4, fj5, fj6, fj7, fj8

      sg_a = (sqrt(d_a(1)*d_a(1) + d_a(2)*d_a(2) + d_a(3)*d_a(3)) - R_a)*(1.0_wp/R_a)
      sg_b = (sqrt(d_b(1)*d_b(1) + d_b(2)*d_b(2) + d_b(3)*d_b(3)) - R_b)*(1.0_wp/R_b)
      if (sg_a > fade_start .or. sg_b > fade_start) then
         ! In or beyond a center's band: faded term, the strip kernel's fade
         if (.not. fade_width > 0.0_wp) error stop &
            "cfc_pair_radius2_eval: fade_width must be positive"
         band_end = fade_start + fade_width
         ! Beyond the band of a center: w = 0, nothing to add
         if (sg_a >= band_end .or. sg_b >= band_end) return
         inv_delta = 1.0_wp/fade_width
         select case (max_deriv)
         case (0)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
               real(wp) :: x17, x18, x19, x20

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a2*(sg_a + sg_b))
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               g_a(0) = fj0*fu
               g_a(1) = fu*(a2*fj0 + fj1)
               g_a(2) = &
                  fu*((a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs &
                  + fp2*fsp2))
               sr = (band_end - (sg_b))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_b - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               g_b(0) = fj0
               g_b(1) = a2*fj0 + fj1
               g_b(2) = &
                  (a2*a2)*fj0 + 2.0_wp*a2*fj1 + (dsdd*dsdd)*fsp3*(20.0_wp*fp0 + 10.0_wp*fp1*fs + &
                  fp2*fsp2)
               x0 = 1.0_wp/R_a
               x1 = 1.0_wp/R_b
               x2 = d_a(1)*d_b(1) + d_a(2)*d_b(2) + d_a(3)*d_b(3)
               x3 = x1*x2
               x4 = x0*x3
               x5 = 2.0_wp - 5.0_wp*x4
               x6 = 4.0_wp*g_a(0)
               x7 = x3*x6
               x8 = (d_a(1)*d_a(1)) + (d_a(2)*d_a(2)) + (d_a(3)*d_a(3))
               x9 = sqrt(x8)
               x10 = g_a(1)*x9
               x11 = 1.0_wp - x4
               x12 = 8.0_wp*x11*x4
               x13 = (x11*x11)
               x14 = c_par*x13
               x15 = g_b(0)*x2
               x16 = x11*x15
               x17 = 4.0_wp*x0
               x18 = (d_b(1)*d_b(1)) + (d_b(2)*d_b(2)) + (d_b(3)*d_b(3))
               x19 = sqrt(x18)
               x20 = g_b(1)*x19
               rr0_aa = &
                  rr0_aa + (g_b(0)*x14*(-x10*x12 + x13*(g_a(2)*x0*x8 + 2.0_wp*x10) - &
                  x5*x7)/(R_a*R_a*R_a))
               rr0_ab = &
                  rr0_ab + (x14*(12.0_wp*g_a(0)*g_b(0)*x0*x1*(x2*x2) + g_a(1)*g_b(1)*x13*x19*x9 - &
                  x10*x16*x17 - x11*x20*x7 - x16*x6)/((R_a*R_a)*(R_b*R_b)))
               rr0_bb = &
                  rr0_bb + (g_a(0)*x14*(-x12*x20 + x13*(g_b(2)*x1*x18 + 2.0_wp*x20) - &
                  x15*x17*x5)/(R_b*R_b*R_b))
            end block
         case (1)
            block
               !> Common subexpressions and symmetry orbits
               real(wp) :: x0, x1, x2, x3, x4, x5, x6, x7, x8, x9, x10, x11, x12, x13, x14, x15, x16
               real(wp) :: x17, x18, x19, x20, x21, x22, x23, x24, x25, x26, x27, x28, x29, x30, x31
               real(wp) :: x32, x33, x34, x35, x36, x37, x38, x39, x40, x41, x42, x43, x44, x45, x46
               real(wp) :: x47, x48, x49, x50, x51, x52, x53, x54, x55, x56, x57, x58, x59, x60, x61
               real(wp) :: x62, x63, x64, x65, x66, x67, x68, x69, x70, x71, x72, x73, x74, x75, x76
               real(wp) :: x77, x78, x79, x80, x81, x82, x83, x84, x85, x86, x87, x88, x89, x90, x91
               real(wp) :: x92, x93, x94, x95, x96, x97, x98, x99, x100, x101, x102, x103, x104
               real(wp) :: x105, x106, x107, x108, x109, x110, x111, x112, x113, x114

               sr = (band_end - (sg_a))*inv_delta
               fs = min(max(sr, 0.0_wp), 1.0_wp)
               ft = min(max((sg_a - fade_start)*inv_delta, 0.0_wp), 1.0_wp)
               dsdd = merge(-inv_delta, 0.0_wp, sr > 0.0_wp .and. sr < 1.0_wp)
               fp0 = ft*(ft*(ft*(70.0_wp*ft + 35.0_wp) + 15.0_wp) + 5.0_wp) + 1.0_wp
               fp1 = ft*(ft*(-280.0_wp*ft - 105.0_wp) - 30.0_wp) - 5.0_wp
               fp2 = ft*(840.0_wp*ft + 210.0_wp) + 30.0_wp
               fp3 = -1680.0_wp*ft - 210.0_wp
               fsp1 = fs
               fsp2 = fsp1*fs
               fsp3 = fsp2*fs
               fsp4 = fsp3*fs
               fsp5 = fsp4*fs
               fu = exp(a2*(sg_a + sg_b))
               fj0 = fp0*fsp5
               fj1 = dsdd*(5.0_wp*fp0*fsp4 + fp1*fsp5)
               fj2 = (a2*a2)
               fj3 = fp2*fsp2
               fj4 = fp1*fs
               fj5 = (dsdd*dsdd)*fsp3*(fj3 + 10.0_wp*fj4 + 20.0_wp*fp0)
               g_a(0) = fj0*fu
               g_a(1) = fu*(a2*fj0 + fj1)
               g_a(2) = fu*(2.0_wp*a2*fj1 + fj0*fj2 + fj5)
               g_a(3) = &
